import {validateModel} from './network.js';
import {startTrial,finishTrial,trialFailure} from './blind-trial.js';
const $=id=>document.getElementById(id);
export function mountLearningLab({onModel,drive,stop,toast,getRecords}){
 let model=null,report=null,baseline=null,baselineReport=null,worker=null,busy=false,history=[];
 let blindRuns=[],blindActive=null,blindRoad=null,lastBlindSave=0;
 try{const saved=JSON.parse(localStorage.getItem('vector-blind-attempts-v1')||'[]');if(Array.isArray(saved))blindRuns=saved.filter(r=>r?.trackId==='harbor-sprint'&&typeof r.id==='string').map(r=>r.outcome==='in-progress'?{...r,outcome:'interrupted: previous session ended'}:r);}catch{}
 const downloadable=(data,name)=>{const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
 function status(message,percent=100){$('training-status').textContent=message;$('training-progress-bar').style.width=percent+'%';}
 function buttons(){for(const id of ['train-button','evaluate-button','drive-test-button','export-model','restore-model','blind-neural'])$(id).disabled=busy||!model;$('import-model').disabled=busy;$('export-report').disabled=busy||!report;$('cancel-training').hidden=!busy;for(const id of ['training-initialization','training-epochs','training-source'])$(id).disabled=busy;$('model-badge').textContent=busy?'COMPUTING':model?'MODEL READY':'NO MODEL';}
 function saveBlind(){try{localStorage.setItem('vector-blind-attempts-v1',JSON.stringify(blindRuns));}catch{toast('Blind-attempt history is in memory; export it before closing.');}}
 function renderBlind(){
  const neural=blindRuns.filter(r=>r.driver==='learned'&&r.modelId===model?.id),count=neural.length;$('blind-neural').textContent=count?'Run neural again':'First neural attempt';$('export-blind').disabled=!blindRuns.length;
  $('blind-status').textContent=blindActive?'ATTEMPT IN PROGRESS':count?`${count} NEURAL ATTEMPT${count===1?'':'S'}`:'NEURAL UNTESTED';
  $('blind-model-note').textContent=blindActive?.driver==='learned'?`Frozen weights · model ${blindActive.modelId.slice(0,8)} · attempt ${blindActive.attemptNumber}`:count?`Current model ${model.id.slice(0,8)} has ${count} recorded attempt${count===1?'':'s'}. Harbor Sprint has never contributed training examples.`:'No neural attempt has been run on this track with the current model. Training and auto-evaluation exclude this course.';
  const container=$('blind-results');container.replaceChildren();if(!blindRuns.length){container.textContent='Your first result will appear here. Attempts are recorded locally, including resets and early stops.';return;}
  const table=document.createElement('table');table.innerHTML='<thead><tr><th>Driver / attempt</th><th>Result</th><th>Complete</th><th>Score</th><th>Time</th><th>Contacts</th></tr></thead>';const body=document.createElement('tbody');for(const r of blindRuns.slice(-10).reverse()){const row=document.createElement('tr');for(const val of [`${r.driver==='learned'?'Neural':r.driver==='manual'?'You':'Reference'} #${r.attemptNumber}${r.firstAttempt?' · FIRST':''}${r.modelId?' / '+r.modelId.slice(0,8):''}`,r.outcome,r.completed?'100%':(r.completionPercent||0).toFixed(1)+'%',r.score==null?'—':r.score+'/100',(r.duration||0).toFixed(1)+' s',String(r.collisions||0)]){const td=document.createElement('td');td.textContent=val;row.append(td);}body.append(row);}table.append(body);container.append(table);
 }
 function beginBlind(road,driver,snapshot,state){if(blindActive)return;const count=blindRuns.filter(r=>r.trackId===road.id&&r.driver===driver&&(driver!=='learned'||r.modelId===snapshot.id)).length;blindActive=startTrial(road,driver,snapshot,state,count+1);blindRoad=road;lastBlindSave=state.time;blindRuns.push({...blindActive,outcome:'in-progress',duration:0,score:null,completionPercent:0});saveBlind();renderBlind();}
 function updateBlind(state){if(!blindActive||state.time-lastBlindSave<1)return;lastBlindSave=state.time;const result={...finishTrial(blindActive,state,'in-progress',blindRoad),finishedAt:null};blindRuns=blindRuns.map(r=>r.id===blindActive.id?result:r);saveBlind();renderBlind();}
 function endBlind(state,outcome){if(!blindActive)return;const result=finishTrial(blindActive,state,outcome,blindRoad);blindRuns=blindRuns.map(r=>r.id===blindActive.id?result:r);blindActive=null;blindRoad=null;saveBlind();renderBlind();toast(`Harbor Sprint · ${result.driver==='learned'?'Neural':'Your'} attempt ${result.attemptNumber} · ${outcome} · ${result.score??'—'}/100`);}
 function drawLoss(){const canvas=$('loss-chart'),c=canvas.getContext('2d'),w=canvas.width,h=canvas.height,left=52,right=12,top=13,bottom=32;c.clearRect(0,0,w,h);c.font='12px monospace';const valid=history.filter(p=>p.loss>0&&p.valLoss>0&&Number.isFinite(p.loss)&&Number.isFinite(p.valLoss));if(!valid.length){c.fillStyle='#7d9574';c.fillText('Training will appear here',left,h/2);return;}const values=valid.flatMap(p=>[p.loss,p.valLoss]);const lo=Math.floor(Math.log10(Math.min(...values))),hi=Math.max(lo+1,Math.ceil(Math.log10(Math.max(...values))));const y=v=>top+(hi-Math.log10(Math.max(v,10**lo)))/(hi-lo)*(h-top-bottom);c.strokeStyle='#2b3d2b';c.fillStyle='#78906d';for(let i=lo;i<=hi;i++){const pos=y(10**i);c.beginPath();c.moveTo(left,pos);c.lineTo(w-right,pos);c.stroke();c.fillText('1e'+i,4,pos+4);}c.fillText('1',left,h-7);c.fillText(String(valid.length),w-35,h-7);for(const [key,color] of [['loss','#d7f878'],['valLoss','#d7a58a']]){c.strokeStyle=color;c.lineWidth=2;c.beginPath();valid.forEach((p,i)=>{const px=left+i/Math.max(1,valid.length-1)*(w-left-right),py=y(p[key]);i?c.lineTo(px,py):c.moveTo(px,py);});c.stroke();}$('epoch-label').textContent=`${valid.length} EPOCHS · LOG MSE`;}
 function modelStats(){if(!model)return;const count=model.layers.reduce((sum,l)=>sum+l.weights.length+l.biases.length,0);$('parameter-count').textContent=`${count.toLocaleString()} parameters`;$('training-count').textContent=`${Number(model.training.samples||0).toLocaleString()} train examples`;$('validation-loss').textContent=`MSE ${Number(model.training.validationLoss||0).toFixed(5)}`;const sizes=[8,...model.layers.map(l=>l.outputs)];document.querySelectorAll('.architecture>span').forEach((el,i)=>el.firstChild.textContent=sizes[i]);$('active-model-label').textContent=`${model.id===baseline?.id?'Bundled model':'Your model'} · Track 1 only · ${model.training.epochs||0} epochs · ${new Date(model.createdAt).toLocaleDateString()}`;history=model.training.history||[];drawLoss();}
 function results(){
  if(!report)return;const passes=report.tracks.reduce((s,t)=>s+t.passed,0),total=report.tracks.reduce((s,t)=>s+t.total,0);$('evaluation-passes').textContent=`${passes} / ${total}`;$('evaluation-summary').textContent=passes===total?'Every tested attempt completed with zero barrier contacts and zero off-track time.':`${total-passes} attempts failed a clean completion. Inspect results before trusting this model.`;
  const body=$('evaluation-rows');body.replaceChildren();for(const t of report.tracks){const r=t.nominal,row=document.createElement('tr');for(const value of [`${t.track} · ${t.role==='test'?'held out':'train'}`,r.completed?'100%':r.completionPercent.toFixed(1)+'%',r.score+'/100',r.offroadSeconds.toFixed(1)+' s',String(r.collisions)]){const td=document.createElement('td');td.textContent=value;row.append(td);}row.children[1].className=r.completed?'pass':'fail';body.append(row);}
  const test=report.tracks.find(t=>t.role==='test');if(test){$('test-lap').innerHTML=`${test.nominal.lapSeconds.toFixed(1)}<small>s</small>`;$('reference-lap').textContent=`Reference: ${test.baseline.lapSeconds.toFixed(1)} s`;$('trajectory-error').innerHTML=`${test.nominal.trajectoryMAEM.toFixed(3)}<small>m</small>`;$('action-error').innerHTML=`${(test.nominal.actionMAE*100).toFixed(1)}<small>%</small>`;}
  const container=$('attempt-results');container.replaceChildren();const table=document.createElement('table');table.innerHTML='<thead><tr><th>Attempt</th><th>Clean</th><th>Score</th><th>Mean offset</th><th>Time</th></tr></thead>';const tbody=document.createElement('tbody');for(const t of report.tracks)for(const [i,r] of [t.nominal,...t.perturbed].entries()){const row=document.createElement('tr');const clean=r.completed&&r.collisions===0&&r.offroadSeconds===0;for(const val of [`${t.track} / ${i===0?'nominal':'recovery '+i}`,clean?'PASS':'FAIL',r.score+'/100',r.meanDeviationM.toFixed(2)+' m',r.lapSeconds.toFixed(1)+' s']){const td=document.createElement('td');td.textContent=val;row.append(td);}tbody.append(row);}table.append(tbody);container.append(table);
 }
 function persist(){try{localStorage.setItem('vector-neural-model-v1',JSON.stringify({model,report}));}catch{toast('The model is in memory. Browser storage is full; export it before closing.');}}
 function activate(next,nextReport){stop();model=validateModel(next);report=nextReport||null;onModel(model);document.getElementById("latest-live-result").textContent='Ready for a live lap with the active model. Choose Neural mode or Drive Track 2.';modelStats();renderBlind();if(report)results();else{$('evaluation-passes').textContent='NOT TESTED';$('evaluation-summary').textContent='This model needs evaluation. Run the 10-attempt suite.';$('evaluation-rows').innerHTML='<tr><td colspan="5">Evaluate this imported model before driving.</td></tr>';$('attempt-results').replaceChildren();for(const id of ['test-lap','trajectory-error','action-error'])$(id).textContent='—';$('reference-lap').textContent='Reference: —';}buttons();}
 function finish(){busy=false;worker?.terminate();worker=null;buttons();}
 function job(type){
  if(busy||!model)return;stop();busy=true;buttons();status(type==='train'?'Preparing expert demonstrations…':'Evaluating frozen weights…',0);
  if(type==='train'){history=[];drawLoss();}
  worker=new Worker('./learning-worker.js',{type:'module'});const jobWorker=worker;
  worker.onmessage=({data})=>{if(worker!==jobWorker||!busy)return;
   if(data.type==='progress')status(data.stage,data.percent);
   if(data.type==='epoch'){history.push(data.item);drawLoss();status(data.stage,data.percent);$('training-count').textContent=`${data.trainingSamples.toLocaleString()} train examples`;$('validation-loss').textContent=`MSE ${data.item.valLoss.toFixed(5)}`;}
   if(data.type==='trained'){activate(data.model,data.report);persist();finish();status('Training complete. Frozen model evaluated on both tracks.');toast('Training finished. Check the held-out results, then try Neural mode.');}
   if(data.type==='evaluated'){report=data.report;results();persist();finish();status('Evaluation complete · 10 measured attempts.');toast('Evaluation complete. Weights stayed frozen for every attempt.');}
   if(data.type==='error'){finish();modelStats();status(data.message,0);toast(data.message);}
  };
  worker.onerror=e=>{finish();status('Learning failed: '+(e.message||'worker error'),0);modelStats();};
  worker.postMessage({type,model,fromScratch:$('training-initialization').value==='scratch',epochs:Number($('training-epochs').value),source:$('training-source').value,records:type==='train'&&$('training-source').value==='manual'?getRecords():[]});
 }
 $('train-button').onclick=()=>job('train');$('evaluate-button').onclick=()=>job('evaluate');$('cancel-training').onclick=()=>{finish();modelStats();status('Cancelled. Your previous model is still active.');toast('Training cancelled. Previous weights retained.');};
 $('training-initialization').onchange=()=>{if($('training-initialization').value==='scratch')$('training-epochs').value='100';};
 $('drive-test-button').onclick=()=>{if(model&&!busy)drive(1);};$('export-model').onclick=()=>downloadable(model,'vector-neural-model.json');$('export-report').onclick=()=>downloadable(report,'vector-evaluation-results.json');
 $('blind-manual').onclick=()=>drive(2,'manual',false);$('blind-neural').onclick=()=>{if(model&&!busy)drive(2,'learned',true);};$('export-blind').onclick=()=>downloadable({track:'harbor-sprint',trainingExcluded:true,autoEvaluationExcluded:true,attempts:blindRuns},'vector-harbor-first-attempts.json');renderBlind();
 $('import-model').onclick=()=>$('model-file').click();$('model-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>2*1024*1024)throw new Error('Model files must be under 2 MB.');const imported=validateModel(JSON.parse(await file.text()));stop();activate(imported,null);persist();status('Imported model. Run evaluation before driving.');toast('Model imported. Its performance has not yet been evaluated.');}catch(error){toast(error.message);}finally{e.target.value='';}};
 $('restore-model').onclick=()=>{stop();activate(structuredClone(baseline),structuredClone(baselineReport));persist();status('Bundled model and its measured results restored.');toast('Bundled model restored.');};
 (async()=>{try{const [m,r]=await Promise.all([fetch('./models/baseline.json'),fetch('./models/evaluation.json')]);if(!m.ok||!r.ok)throw new Error('Bundled model could not load.');baseline=validateModel(await m.json());baselineReport=await r.json();let saved;try{saved=JSON.parse(localStorage.getItem('vector-neural-model-v1')||'null');if(saved)validateModel(saved.model);}catch{saved=null;}activate(saved?.model||baseline,saved && saved.report?.modelId===saved.model?.id?saved.report:!saved?baselineReport:null);status('Ready · Track 1 trained weights. Retrain or test the neural driver.');}catch(error){status(error.message,0);buttons();toast(error.message);}})();
 return {getModel:()=>model,beginBlind,updateBlind,endBlind,blindFailure:state=>trialFailure(blindActive,state),finishDrive:(road,state)=>{const lap=state.finishedLaps.at(-1),baselineTime=report?.tracks.find(t=>t.trackId===road.id)?.baseline.lapSeconds;const message=`Live neural lap · ${road.name} · ${lap.time.toFixed(1)} s · ${lap.score}/100 · ${lap.collisions} contacts · ${lap.offroadTime.toFixed(1)} s off track${baselineTime?` · reference ${baselineTime.toFixed(1)} s`:''}`;$('latest-live-result').textContent=message;toast(message);}};
}



